import { Threshold } from '../../../core/types/threshold-types.js';
import { getThresholdColor } from '../../../core/utils/threshold-utils.js';
import { getValidColor } from '../../core/functions/getValidColor.js';

export const useThresholds = (
  inputValue: string | number,
  inputColor: string | undefined,
  thresholds: Threshold[] | undefined,
): string => {
  const hasThresholds = thresholds && thresholds.length > 0;
  const calculatedColor = hasThresholds
    ? getThresholdColor(inputValue, thresholds) || inputColor
    : inputColor;

  return getValidColor(calculatedColor);
};
